def run(deg_a, deg_b, deg_c, deg_s):
    best=(1,None)
    for q in np.linspace(1.0,3.0,41):
      for k in np.linspace(4,60,57):
        u=eps/T**q
        S=1-np.exp(-k*u)
        cols=[T**j for j in range(deg_a+1)]+[S*T**j for j in range(deg_b+1)]+[eps*T**j for j in range(deg_c+1)]+[eps**2*T**j for j in range(deg_s+1)]
        X=np.column_stack(cols)
        v,c=nm(X)
        if v<best[0]: best=(v,(round(q,3),round(k,2),np.round(c,4)))
    return best
